{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "There is limited evidence to evaluate the sustainability of evidence-based interventions (EBIs) for healthcare improvement. ... It is unclear which approach/approaches are most effective for evaluating sustainability and what measures and outcomes are most commonly used. There is a disconnect between evaluating the factors that may shape sustainability and the outcomes approaches employed to measure sustainability.",
      "reason": "The text explicitly describes the current state of knowledge (limited evidence) and important uncertainties (unclear which approaches are effective, disconnect between factors and outcomes)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated. A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The text explains the need for the review, specifically to improve understanding of how sustainability is evaluated, which differentiates it from existing syntheses."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. ... Our synthesis indicated that there is a breadth of theoretical approaches and constructs that were considered for the evaluation of the sustainability of EBIs in healthcare that were consistent with other recent synthesis work [6-10].",
      "reason": "The authors acknowledge existing syntheses (citing them as [6-10]) and explain how their review differs (focus on evaluation vs. determinants)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review of approaches to evaluate sustainability, not a review of the effects of a specific intervention; therefore, a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not evaluating a specific complex intervention or delivery context that requires a logic model; it is a methodological review of evaluation approaches."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review explicitly states its primary objective and secondary aims in the 'Aim' section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review focused on identifying approaches to evaluate sustainability, not a review of intervention effects comparing specific interventions, so PICO is not applicable."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Articles were included if they: • Were published in a peer-review journal • Were primary research • Had explicit research design and data collection methods • Had an explicit theoretical ­ approach a for sustainability ­ (theory b , ­ model c , ­ framework d , ­ instrument e , method, checklist, process, strategy, conceptual- izations, development, pilot test and/or ­ tool f ) • Were within a healthcare ­ setting g • Evaluated the sustainability of an EBI",
      "reason": "The manuscript provides a comprehensive table (Table 1) detailing inclusion and exclusion criteria, covering publication type, study design, theoretical approach, setting, and the requirement to evaluate sustainability of an EBI."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_21",
      "quote": "We only included published studies in the English language and peer-reviewed primary studies in this review.",
      "reason": "The manuscript specifies language (English) and publication status (peer-reviewed primary studies) as part of the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not appear to have excluded studies based on the distinction between outcomes not measured versus outcomes not reported; the exclusion criteria focus on the presence of an evaluation component and research design."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "While the manuscript describes the data extraction and analysis process, it does not explicitly define how studies were grouped for synthesis (e.g., by study design, theoretical approach, or outcome type) in relation to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "table_0",
      "quote": "Exclusion criteria: • Were secondary research • Were gray literature • Were outside a healthcare context (e.g., schools, social care settings) • Did not evaluate the sustainability of an EBI or QI intervention using a defined approach or, • Did not evaluate sustainability using a clear research design and method • Did not have an independent evaluation component on sustainability • Focused only on the sustainability of clinical outcome without a tangible approach • Focused only on defining or constructing concepts of sustainability",
      "reason": "The manuscript provides rationales for the exclusion criteria, such as excluding gray literature and studies without independent evaluation components, to ensure the focus remains on primary research evaluating sustainability approaches."
    }
  ],
  "confidence": 90
}

